<template>
  <ContentWrap><el-form inline :model="query"><el-form-item label="年度"><el-input-number v-model="query.year" :controls="false"/></el-form-item><el-form-item label="合同名称"><el-input v-model="query.contractName" clearable/></el-form-item><el-form-item label="合同编号"><el-input v-model="query.contractNo" clearable/></el-form-item><el-form-item label="完成状态"><el-select v-model="query.completionStatus" clearable class="!w-120px"><el-option label="未完成" :value="0"/><el-option label="已完成" :value="1"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="load"><Icon icon="ep:search"/>查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></ContentWrap>
  <ContentWrap><el-table v-loading="loading" :data="list" stripe><el-table-column prop="contractNo" label="合同编号" width="160"/><el-table-column prop="contractName" label="项目/合同名称" min-width="220"/><el-table-column prop="year" label="年度" width="90"/><el-table-column label="项目类型" width="100"><template #default="s">{{['','建设','服务','其他'][s.row.projectType]}}</template></el-table-column><el-table-column label="归档进度" width="220"><template #default="s"><el-progress :percentage="s.row.completionPercent"/></template></el-table-column><el-table-column label="完成项" width="100"><template #default="s">{{s.row.completedCount}}/{{s.row.totalCount}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row.id)">维护详情</el-button></template></el-table-column></el-table><Pagination :total="total" v-model:page="query.pageNo" v-model:limit="query.pageSize" @pagination="load"/></ContentWrap>
  <el-drawer v-model="visible" title="项目归档维护" size="900px"><ProjectArchivePanel v-if="currentId" :archive-id="currentId"/></el-drawer>
</template>
<script setup lang="ts">
import {ProjectArchiveApi,type ProjectArchive} from '@/api/yideyifeng/projectArchive';import ProjectArchivePanel from './ProjectArchivePanel.vue'
const loading=ref(false);const list=ref<ProjectArchive[]>([]);const total=ref(0);const visible=ref(false);const currentId=ref<number>();const query=reactive({pageNo:1,pageSize:10,year:undefined as number|undefined,contractName:'',contractNo:'',completionStatus:undefined as number|undefined})
const load=async()=>{loading.value=true;try{const data=await ProjectArchiveApi.getPage(query);list.value=data.list;total.value=data.total}finally{loading.value=false}};const reset=()=>{query.year=undefined;query.contractName='';query.contractNo='';query.completionStatus=undefined;query.pageNo=1;load()};const open=(id:number)=>{currentId.value=id;visible.value=true};onMounted(load)
</script>
